 int flb_unescape_string(const char *buf, int buf_len, char **unesc_buf)
 {
     int i = 0;
     int j = 0;
     char *p;
     char n;

     p = *unesc_buf;
     while (i < buf_len) {
         if (buf[i] == '\\') {
             if (i + 1 < buf_len) {
                 n = buf[i + 1];
                 if (n == 'n') {
                     p[j++] = '\n';
                     i++;
                 }
                 else if (n == 'a') {
                     p[j++] = '\a';
                     i++;
                 }
                 else if (n == 'b') {
                     p[j++] = '\b';
                     i++;
                 }
                 else if (n == 't') {
                     p[j++] = '\t';
                     i++;
                 }
                 else if (n == 'v') {
                     p[j++] = '\v';
                     i++;
                 }
                 else if (n == 'f') {
                     p[j++] = '\f';
                     i++;
                 }
                 else if (n == 'r') {
                     p[j++] = '\r';
                     i++;
                 }
                 else if (n == '\\') {
                     p[j++] = '\\';
                     i++;
                 }
                 i++;
                 continue;
             }
             else {
                 i++;
             }
         }
         p[j++] = buf[i++];
     }
     p[j] = '\0';
     return j;
 }


